model:
rachana: 1
sutra: lei-entity
version: 1
description: 
match: { kind: lei-entity, priority: 10 }
title: { pill: "GLEIF · Legal entity", id: "$.LEI", with: "$.NAME" }
strip:
  - { label: "Country", bind: "link($.LEI_COUNTRY, 'lei-country', $.COUNTRY_NAME)" }
  - { label: "Legal form", bind: "$.LEGAL_FORM" }
  - { label: "Entity", bind: "$.ENTITY_STATUS" }
  - { label: "Registration", bind: "$.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $.REGISTRATION_STATUS", tone: "status", emphasis: true }
  - { label: "Renewal", bind: "$.RENEWAL_LATE ? 'Late: renewal failed by ' + $.NEXT_RENEWAL : (nonblank($.RENEWAL) ? 'Pending: due ' + $.NEXT_RENEWAL : 'Renewed to ' + $.NEXT_RENEWAL)", tone: "status" }
  - { label: "Children", bind: "nonblank($.CHILD_COUNT, 0)", fmt: "entities0" }
  - { label: "Ownership group", bind: "link($.LEI_GROUP, 'lei-group', $.LEI_GROUP == $.LEI ? 'Its own group' : last($.PARENTS).NAME)" }
panels:
  - id: parents
    kind: table
    title: "Parents chain (the ultimate parent at the top, down to this entity)"
    key: "F2"
    code: "PAR"
    rows: "take($.PARENTS, -1)"
    children: "@.LEI == $.LEI ? null : (@.LEVEL == 1 ? $ : let(k = @.LEVEL, $.PARENTS[?@.LEVEL == k - 1]))"
    expand: "all"
    highlight: "@.LEI == $.LEI"
    search: false
    when: "size($.PARENTS) > 0"
    columns:
      - { label: "Entity", bind: "link(@.LEI, 'lei-entity', @.NAME)" }
      - { label: "Relationship", bind: "@.LEI == $.LEI ? 'This entity' : @.RELATIONSHIP" }
      - { label: "Level", bind: "@.LEVEL" }
      - { label: "LEI", bind: "@.LEI" }
  - id: children
    kind: table
    title: "Children (a click opens one beside)"
    key: "F3"
    code: "KIDS"
    rows: "$.CHILDREN"
    empty: "No children in the pack: it consolidates no entity that reports it as direct parent"
    columns:
      - { label: "Legal name", bind: "@.NAME" }
      - { label: "Country", bind: "@.COUNTRY" }
      - { label: "Their children", bind: "@.KIDS" }
      - { label: "LEI", bind: "@.LEI" }
  - id: card
    kind: kv
    title: "Key facts"
    code: "FACTS"
    area: right
    columns:
      - { label: "Legal name", bind: "link($.LEI, 'lei-entity', $.NAME)" }
      - { label: "LEI", bind: "$.LEI" }
      - { label: "Legal form", bind: "$.LEGAL_FORM" }
      - { label: "Category", bind: "nonblank($.CATEGORY, 'General')" }
      - { label: "Jurisdiction", bind: "nonblank($.JURISDICTION, $.LEI_COUNTRY)" }
      - { label: "Country", bind: "link($.LEI_COUNTRY, 'lei-country', $.COUNTRY_NAME)" }
      - { label: "City", bind: "$.LEGAL_CITY" }
      - { label: "Registered as", bind: "$.REGISTERED_AS" }
      - { label: "Entity status", bind: "$.ENTITY_STATUS" }
      - { label: "Registration", bind: "$.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $.REGISTRATION_STATUS", tone: "status" }
      - { label: "Next renewal", bind: "$.NEXT_RENEWAL", fmt: "date" }
      - { label: "Managing LOU", bind: "$.MANAGING_LOU" }
      - { label: "Direct parent", bind: "link($.DIRECT_PARENT, 'lei-entity')" }
      - { label: "Ownership group", bind: "link($.LEI_GROUP, 'lei-group')" }
      - { label: "Children in the pack", bind: "$.CHILD_COUNT", fmt: "entities0" }
      - { label: "BICs", bind: "$.BICS" }
      - { label: "ISINs (GLEIF mapping)", bind: "$.ISIN_COUNT", fmt: "entities0" }
  - id: addresses
    kind: kv
    title: "Addresses"
    area: right
    columns:
      - { label: "Legal address", bind: "$.LEGAL_ADDRESS" }
      - { label: "Headquarters", bind: "nonblank($.HQ_ADDRESS, 'Same as the legal address')" }
      - { label: "Headquarters country", bind: "nonblank($.HQ_COUNTRY, $.LEI_COUNTRY)" }
  - id: registration
    kind: status
    title: "Registration and renewal"
    key: "F4"
    area: right
    fields: [{ label: "Registration status", bind: "$.REGISTRATION_STATUS == 'LAPSED' ? 'LAPSED: renewal failed' : $.REGISTRATION_STATUS", tone: "status" }, { label: "Renewal", bind: "$.RENEWAL_LATE ? 'Late: renewal failed by ' + $.NEXT_RENEWAL : (nonblank($.RENEWAL) ? 'Pending: due ' + $.NEXT_RENEWAL : 'Renewed to ' + $.NEXT_RENEWAL)", tone: "status" }, { label: "First registered", bind: "$.INITIAL_REGISTRATION", fmt: "date" }, { label: "Last updated", bind: "$.LAST_UPDATE", fmt: "date" }, { label: "Next renewal", bind: "$.NEXT_RENEWAL", fmt: "date" }, { label: "Entity created", bind: "$.CREATED", fmt: "date" }, { label: "Managing LOU", bind: "$.MANAGING_LOU" }, { label: "GLEIF record", bind: "'https://search.gleif.org/#/record/' + $.LEI" }]
  - id: identifiers
    kind: kv
    title: "Identifiers"
    area: right
    columns:
      - { label: "LEI", bind: "$.LEI" }
      - { label: "BICs", bind: "nonblank($.BICS, 'None mapped')" }
      - { label: "ISINs mapped", bind: "nonblank($.ISIN_COUNT, 0)", fmt: "entities0" }
      - { label: "MIC", bind: "$.MIC" }
      - { label: "OpenCorporates", bind: "nonblank($.OPENCORPORATES) ? 'https://opencorporates.com/companies/' + $.OPENCORPORATES : ''" }
      - { label: "Other names", bind: "first($.OTHER_NAMES).NAME" }
  - id: listed
    kind: kv
    title: "US listed company (us-equities)"
    area: right
    when: "nonblank($.US_COMPANY)"
    columns:
      - { label: "Company", bind: "link($.US_COMPANY, 'us-company', $.US_COMPANY_NAME)" }
      - { label: "Ticker", bind: "$.US_COMPANY" }
      - { label: "Why in this pack", bind: "$.SEGMENT" }
  - id: exceptions
    kind: table
    title: "Reporting exceptions (why no parent is reported)"
    area: right
    rows: "$.PARENT_EXCEPTIONS"
    search: false
    when: "size($.PARENT_EXCEPTIONS) > 0"
    columns:
      - { label: "For", bind: "@.LEVEL" }
      - { label: "Reason", bind: "@.REASON" }
      - { label: "Meaning", bind: "@.MEANING" }
  - id: refs
    kind: links
    title: "Linked entities and identifiers"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
  - id: note
    kind: markdown
    title: "About this page"
    area: right
    phone: { tier: "more", from: "fragment" }
    text: "Public data from GLEIF (CC0 1.0; attribution appreciated): the entity's level 1 LEI record, its consolidation relationships from the level 2 golden copy and its identifiers from GLEIF's BIC, ISIN, MIC and OpenCorporates mapping files. A renewal is late when the record lapsed or its next renewal date has passed. The children are those the pack keeps (at most 50 a group, the nearest levels first): the group page says when a group is larger."
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F5: "link($.LEI_GROUP, 'lei-group', 'Ownership group')", F6: "link($.LEI_COUNTRY, 'lei-country', 'Country')", F7: "link(nonblank($.DIRECT_PARENT) ? 'LEIREL-' + $.LEI + '-DIRECT' : (nonblank($.ULTIMATE_PARENT) ? 'LEIREL-' + $.LEI + '-ULTIMATE' : ''), 'lei-relationship', 'Parent relationship')", F8: "link($.US_COMPANY, 'us-company', 'Listed company')", F9: "raw" }
